@import url('https://fonts.googleapis.com/css2?family=Roboto:wght@400;500;600;700&family=JetBrains+Mono:wght@400;500;600;700&display=swap');

/* LinkedIn DNA — warm paper feed, white cards, professional blue, pill actions */
.theme-linkedin-dna {
  --bg: oklch(0.962 0.006 84.6);
  --surface: oklch(1.000 0 0);
  --surface-2: oklch(0.945 0.011 76.6);
  --fg: oklch(0.213 0 0);
  --fg-muted: oklch(0.510 0 0);
  --accent: oklch(0.516 0.163 254.7);
  --accent-fg: oklch(1.000 0 0);
  --accent-2: oklch(0.497 0.109 162.1);
  --line: oklch(0.891 0.016 77.1);
  --success: oklch(0.497 0.109 162.1);
  --warning: oklch(0.764 0.139 73.2);
  --danger: oklch(0.536 0.213 27.7);
  --radius: 0.5rem;
  --radius-sm: 0.25rem;
  --radius-lg: 0.75rem;
  --radius-pill: 9999px;
  --shadow-1: 0 1px 2px oklch(0 0 0 / 8%);
  --shadow-2: 0 6px 20px -8px oklch(0 0 0 / 15%);
  --shadow-3: 0 20px 50px -16px oklch(0 0 0 / 20%);
  --glow: 0 0 0 1px color-mix(in oklab, var(--accent) 45%, transparent);
  --border-width: 1px;
  --blur-amount: 0px;
  --font-display: -apple-system, "Segoe UI", Roboto, "Helvetica Neue", sans-serif;
  --font-body: -apple-system, "Segoe UI", Roboto, "Helvetica Neue", sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;
  --tracking-display: -0.01em;
  --label-transform: none;
  --label-tracking: 0.05em;

  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}

.theme-linkedin-dna h1,
.theme-linkedin-dna h2,
.theme-linkedin-dna h3 {
  font-family: var(--font-display);
  letter-spacing: var(--tracking-display);
}

/* signature */
.theme-linkedin-dna { --font-ui: var(--font-display); }
.theme-linkedin-dna h1 { font-weight: 600; }
.theme-linkedin-dna button { font-weight: 600; }
.theme-linkedin-dna h2::after { content: ""; display: block; width: 3rem; height: 3px; background: var(--accent); margin-top: 0.5rem; }

/* depth */
.theme-linkedin-dna thead th { background: var(--surface-2); font-size: 0.8em; font-weight: 600; color: var(--fg-muted); border-bottom: 1px solid var(--line); }
.theme-linkedin-dna td { border-bottom: 1px solid var(--line); }
.theme-linkedin-dna tbody tr:hover { background: oklch(0.97 0.008 80); }
.theme-linkedin-dna a { color: var(--accent); font-weight: 600; text-decoration: none; }
.theme-linkedin-dna a:hover { text-decoration: underline; color: oklch(0.42 0.16 254.7); }
.theme-linkedin-dna input, .theme-linkedin-dna textarea, .theme-linkedin-dna select { background: var(--surface); border: 1px solid oklch(0.45 0 0 / 60%); border-radius: var(--radius-sm); }
.theme-linkedin-dna input:focus-visible, .theme-linkedin-dna textarea:focus-visible, .theme-linkedin-dna select:focus-visible { outline: none; border-color: var(--accent); box-shadow: 0 0 0 1px var(--accent); }
.theme-linkedin-dna kbd { font-family: var(--font-body); font-size: 0.85em; background: var(--surface-2); border: 1px solid var(--line); border-radius: 0.3rem; padding: 0.1em 0.45em; }
.theme-linkedin-dna ::selection { background: oklch(0.88 0.05 255); }
.theme-linkedin-dna ::-webkit-scrollbar { width: 10px; height: 10px; }
.theme-linkedin-dna ::-webkit-scrollbar-track { background: var(--bg); }
.theme-linkedin-dna ::-webkit-scrollbar-thumb { background: oklch(0.7 0.01 80); border-radius: 5px; }
.theme-linkedin-dna .label-caps { color: var(--fg-muted); font-weight: 600; }
.theme-linkedin-dna .themed-border { border-top: 4px solid var(--accent); border-radius: var(--radius); }
.theme-linkedin-dna button:hover { box-shadow: inset 0 0 0 1px currentColor; } /* double-border hover */
.theme-linkedin-dna button:active { filter: brightness(0.92); }

/* alt mode: LinkedIn's real dark — black canvas, #1B1F23 cards, light-blue links */
.theme-linkedin-dna.alt-mode {
  --bg: oklch(0 0 0);
  --surface: oklch(0.235 0.008 250);
  --surface-2: oklch(0.29 0.008 250);
  --fg: oklch(0.93 0.003 250);
  --fg-muted: oklch(0.68 0.005 250);
  --accent: oklch(0.52 0.14 250);
  --accent-fg: oklch(1 0 0);
  --accent-2: oklch(0.75 0.11 250);
  --line: oklch(1 0 0 / 15%);
  --shadow-1: 0 1px 2px oklch(0 0 0 / 60%);
  --shadow-2: 0 8px 24px oklch(0 0 0 / 60%);
  --shadow-3: 0 24px 56px oklch(0 0 0 / 70%);
}
.theme-linkedin-dna.alt-mode a, .theme-linkedin-dna.alt-mode .text-accent { color: oklch(0.75 0.11 250); }
.theme-linkedin-dna.alt-mode button[class*="outline"], .theme-linkedin-dna.alt-mode button[class*="ghost"] { border-color: oklch(0.75 0.11 250); color: oklch(0.75 0.11 250); }
.theme-linkedin-dna.alt-mode h2::after { background: oklch(0.75 0.11 250); }
.theme-linkedin-dna.alt-mode tbody tr:hover { background: oklch(0.27 0.008 250); }
.theme-linkedin-dna.alt-mode input, .theme-linkedin-dna.alt-mode textarea { background: oklch(0.29 0.008 250); border-color: oklch(1 0 0 / 20%); }

/* fidelity: LinkedIn controls — pill buttons everywhere, outline-blue secondary */
.theme-linkedin-dna button { border-radius: 9999px; font-weight: 600; }
.theme-linkedin-dna button[class*="outline"] { border: 1px solid oklch(0.47 0.13 250); color: oklch(0.47 0.13 250); background: transparent; }
.theme-linkedin-dna button[class*="outline"]:hover { background: oklch(0.47 0.13 250 / 8%); box-shadow: inset 0 0 0 1px oklch(0.47 0.13 250); }
.theme-linkedin-dna button[class*="ghost"] { border-radius: 9999px; color: oklch(0.4 0.01 80); font-weight: 600; }
.theme-linkedin-dna nav span.bg-accent { border-radius: 0; border-left: 3px solid oklch(0.47 0.13 250); background: oklch(0.47 0.13 250 / 9%); color: oklch(0.35 0.1 250); }
.theme-linkedin-dna input, .theme-linkedin-dna textarea { border-radius: 0.25rem; background: oklch(0.93 0.008 250 / 60%); }
.theme-linkedin-dna h1 { font-weight: 600; }
.theme-linkedin-dna span.rounded-theme-pill { font-weight: 600; }
.theme-linkedin-dna td { border-bottom: 1px solid oklch(0.9 0.005 80); }
.theme-linkedin-dna th { font-weight: 600; color: oklch(0.45 0.01 80); }
.theme-linkedin-dna.alt-mode nav span.bg-accent { background: oklch(0.75 0.11 250 / 12%); color: oklch(0.75 0.11 250); border-left-color: oklch(0.75 0.11 250); }
.theme-linkedin-dna.alt-mode button[class*="outline"] { border-color: oklch(0.75 0.11 250); color: oklch(0.75 0.11 250); }
.theme-linkedin-dna.alt-mode input, .theme-linkedin-dna.alt-mode textarea { background: oklch(0.29 0.008 250); }

/* Bridge shadcn semantic variables to the theme tokens so stock shadcn/ui
   components are skinned by the theme. Scope-safe: applies inside the theme
   class only. */
[class*="theme-"] {
  --background: var(--bg);
  --foreground: var(--fg);
  --card: var(--surface);
  --card-foreground: var(--fg);
  --popover: var(--surface);
  --popover-foreground: var(--fg);
  --primary: var(--accent);
  --primary-foreground: var(--accent-fg);
  --secondary: var(--surface-2);
  --secondary-foreground: var(--fg);
  --muted: var(--surface-2);
  --muted-foreground: var(--fg-muted);
  --accent-foreground: var(--accent-fg);
  --border: var(--line);
  --input: var(--line);
  --ring: var(--accent);
  --destructive: var(--danger);
  --destructive-foreground: var(--accent-fg);

  /* Full app surface: sidebar, charts, app-level font + shadow + tracking vars.
     These are what real products (shadcn full kit, RootCX-style UI kits) consume —
     without them a retrofit looks half-themed. */
  --sidebar: var(--surface-2);
  --sidebar-foreground: var(--fg);
  --sidebar-primary: var(--accent);
  --sidebar-primary-foreground: var(--accent-fg);
  --sidebar-accent: color-mix(in oklab, var(--accent) 12%, var(--surface-2));
  --sidebar-accent-foreground: var(--fg);
  --sidebar-border: var(--line);
  --sidebar-ring: var(--accent);

  --chart-1: var(--accent);
  --chart-2: var(--accent-2);
  --chart-3: var(--success);
  --chart-4: var(--warning);
  --chart-5: var(--danger);

  --font-sans: var(--font-body);
  --font-heading: var(--font-display);
  --font-serif: var(--font-display);

  --shadow-2xs: var(--shadow-1);
  --shadow-xs: var(--shadow-1);
  --shadow-sm: var(--shadow-1);
  --shadow: var(--shadow-2);
  --shadow-md: var(--shadow-2);
  --shadow-lg: var(--shadow-3);
  --shadow-xl: var(--shadow-3);
  --shadow-2xl: var(--shadow-3);

  --tracking-normal: 0em;
}

/* Base experience: make the theme own the canvas and native elements even in
   apps that never adopted semantic classes. Scoped to the theme wrapper. */
[class*="theme-"] {
  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}
[class*="theme-"] :is(h1, h2, h3, h4) { font-family: var(--font-display); }
[class*="theme-"] :is(code, pre, kbd, samp) { font-family: var(--font-mono); }
[class*="theme-"] ::selection { background: color-mix(in oklab, var(--accent) 30%, transparent); }
